import org.springframework.http.HttpHeaders;
import org.springframework.web.filter.GenericFilterBean;

public class ThrottlingFilter extends GenericFilterBean {
    private int maxRequests = 10; // adjust this value as needed
    private long lastRequestTime = System.currentTimeMillis();

    @Override
    public void doFilter(ServletRequest request, ServletResponse response, FilterChain chain) throws IOException, ServletException {
        HttpHeaders headers = (HttpHeaders) request.getAttribute("headers");
        if (headers == null) {
            headers = new HttpHeaders();
            ((ServletRequestAttributes) RequestContextHolder.currentRequestAttributes()).getRequest().setAttribute("headers", headers);
        }
        long currentTime = System.currentTimeMillis();
        if (currentTime - lastRequestTime < 1000 * maxRequests) { // adjust this value as needed
            return;
        }
        lastRequestTime = currentTime;
        chain.doFilter(request, response);
    }
}
```
